CREATE DATABASE college;

USE college;

CREATE TABLE students (
  usn STRING,
  name STRING,
  cgpa DOUBLE
);

SELECT name, cgpa
FROM students
WHERE cgpa >= 8.0;

A = LOAD 'students.csv' USING PigStorage(',');
B = FILTER A BY cgpa >= 8.0;
C = FOREACH B GENERATE name, cgpa;
DUMP C;

J = JOIN students BY dept, departments BY dept;
S = ORDER students BY cgpa DESC;
T = LIMIT S 10;

G = GROUP students BY dept;
R = FOREACH G GENERATE group,
    COUNT(students),
    AVG(students.cgpa);

G = GROUP students BY dept;
-- Each group contains a bag of student tuples
DUMP G;
